// Общий код для «звонок → склейка частей записи → транскрипт → отчёт» (#3257d0efcc42561f5bc1ef6c, кейсы REC-002, REC-003).
// Кандидат — отдельный Chrome с фальшивым микрофоном (файл зацикливается), сеть записывается:
// POST/PUT recording-upload-url (индексы частей), POST end-candidate-attempt (время склейки).
// business — окно из asUser('business'): опрос get_candidate_report, файл записи, плеер отчёта.
import { chromium, Browser, Page, Request, Response } from '@playwright/test';
import * as path from 'path';
import { expect } from '../../fixtures';
import { openWithApi, Api } from '../support/api';
import { tap } from '../candidate-call/support';

export const WAV = path.resolve(__dirname, '../../../audio/g4/A.wav'); // 7.3 мин, Chrome повторяет по кругу

export type CallLog = {
  tickets: number[]; // индексы частей, на которые выдан билет (POST recording-upload-url 2xx)
  puts: { idx: number | null; status: number }[]; // все ответы PUT частей (с повторами)
  endReqAt?: number; // локальное время отправки POST end-candidate-attempt
  endRespAt?: number; // локальное время ответа на него
  endStatus?: number;
  endBody?: { attempt?: { end_reason?: string; duration_seconds?: number }; recording?: { is_partial?: boolean } };
  errors: string[];
};

export type Guest = { browser: Browser; page: Page; log: CallLog };

const partIdx = (p?: string) => {
  const m = /parts\/(\d+)\./.exec(p || '');
  return m ? Number(m[1]) : null;
};

/** Chrome кандидата (мобильный вид 390×844) с фальшивым микрофоном и записью сети звонка. */
export async function launchGuest(): Promise<Guest> {
  const browser = await chromium.launch({
    channel: process.env.QA_CALL_CHANNEL || 'chrome',
    args: [
      '--use-fake-ui-for-media-stream',
      '--use-fake-device-for-media-stream',
      `--use-file-for-fake-audio-capture=${WAV}`,
      '--autoplay-policy=no-user-gesture-required',
    ],
  });
  const ctx = await browser.newContext({ locale: 'he-IL', viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, permissions: ['microphone'] });
  const page = await ctx.newPage();
  const log: CallLog = { tickets: [], puts: [], errors: [] };
  page.on('request', (r: Request) => {
    if (r.method() === 'POST' && r.url().includes('/functions/v1/end-candidate-attempt')) log.endReqAt = Date.now();
  });
  page.on('response', async (r: Response) => {
    const u = r.url();
    const m = r.request().method();
    try {
      if (u.includes('/functions/v1/end-candidate-attempt') && m === 'POST') {
        log.endRespAt = Date.now();
        log.endStatus = r.status();
        log.endBody = await r.json().catch(() => undefined);
      } else if (u.includes('recording-upload-url')) {
        const body = (await r.json().catch(() => ({}))) as { path?: string };
        if (m === 'POST' && r.status() < 300) {
          const i = partIdx(body.path);
          if (i !== null) log.tickets.push(i);
        } else if (m === 'PUT') {
          log.puts.push({ idx: partIdx(body.path), status: r.status() });
        }
      }
    } catch (e) {
      log.errors.push(`${m} ${u.split('?')[0].slice(-60)}: ${String(e).slice(0, 120)}`);
    }
  });
  return { browser, page, log };
}

/** Кандидат: вступление → тех. проверка → пропуск практики → официальный звонок начат. */
export async function startOfficialCall(page: Page, link: string) {
  await page.goto(link);
  await tap(page, 'בוא נתחיל');
  await tap(page, 'לראות פרטי לקוח');
  await tap(page, 'להמשיך');
  await page.getByRole('checkbox').first().check();
  await tap(page, /^להתחיל$/);
  await tap(page, 'להתחיל בדיקה');
  await tap(page, 'כן, שומעים טוב', 60_000);
  await tap(page, 'להמשיך לתרגול');
  await tap(page, 'לדלג ישר לשיחה הרשמית');
  await page.getByRole('checkbox', { name: /ניסיון חד-פעמי/ }).check();
  await tap(page, 'מוכן, מתחילים');
  await expect(page.getByRole('button', { name: 'לסיים שיחה' })).toBeVisible({ timeout: 60_000 });
}

export const okParts = (log: CallLog) => new Set(log.puts.filter((p) => p.idx !== null && p.status < 300).map((p) => p.idx as number));

/** Все выданные билеты получили успешный PUT (повтор после 5xx допустим), индексы 0…N-1 без пропусков. */
export async function expectAllPartsUploaded(log: CallLog) {
  await expect
    .poll(() => log.tickets.filter((i) => !okParts(log).has(i)), { message: 'части с билетом, но без успешного PUT', timeout: 60_000 })
    .toEqual([]);
  const ok = [...okParts(log)].sort((a, b) => a - b);
  const missing = ok.length ? Array.from({ length: ok[ok.length - 1] + 1 }, (_, i) => i).filter((i) => !ok.includes(i)) : [];
  expect(ok[0], 'первая часть — 000000').toBe(0);
  expect(missing, 'пропуски в индексах частей').toEqual([]);
  expect(log.errors).toEqual([]);
  return ok.length;
}

type ReportJson = {
  report?: { status?: string; generated_at?: string | null };
  attempt?: { transcription_status?: string; ended_at?: string; duration_seconds?: number; end_reason?: string };
  recording?: { is_partial?: boolean; duration_seconds?: number };
  transcript?: { segments?: { start: number; end: number; text: string; speaker: string }[] };
};

export async function candidateId(api: Api, name: string): Promise<string> {
  const rows = (await (await api.get(`candidates?select=id&full_name=eq.${encodeURIComponent(name)}`)).json()) as { id: string }[];
  expect(rows, `кандидат «${name}» не найден`).toHaveLength(1);
  return rows[0].id;
}

export async function getReport(api: Api, id: string): Promise<ReportJson> {
  const res = await api.rpc('get_candidate_report', { p_candidate_id: id, p_reason: null });
  expect(res.ok(), `get_candidate_report ${res.status()}`).toBeTruthy();
  const j = await res.json();
  return (Array.isArray(j) ? j[0] : j) as ReportJson;
}

/**
 * Опрос отчёта после конца звонка: момент, когда transcription_status = completed и когда report.status = ready.
 * Возвращает секунды от attempt.ended_at (часы сервера) до первого увиденного «completed» и generated_at отчёта.
 */
export async function waitTranscriptAndReport(api: Api, id: string) {
  let r: ReportJson = {};
  await expect
    .poll(async () => (r = await getReport(api, id)).attempt?.ended_at || '', { message: 'attempt.ended_at не появился', timeout: 60_000 })
    .not.toBe('');
  const endedAt = Date.parse(r.attempt!.ended_at!);
  // Транскрипт: AC — «התמלול מוכן בתוך 300 שניות מסוף השיחה». Опрос каждые 3 с до 300 с от конца (+5 с на опрос).
  const left = Math.max(5_000, endedAt + 305_000 - Date.now());
  await expect
    .poll(async () => (r = await getReport(api, id)).attempt?.transcription_status, {
      message: 'транскрипт не готов в пределах 300 с от конца звонка',
      timeout: left,
      intervals: [3_000],
    })
    .toBe('completed');
  const transcriptSec = (Date.now() - endedAt) / 1000;
  // Отчёт: decisions — «סך הזמן עד דוח מוכן אינו עולה על 10 דקות».
  await expect
    .poll(async () => (r = await getReport(api, id)).report?.status, { message: 'отчёт не ready за 10 мин', timeout: Math.max(5_000, endedAt + 600_000 - Date.now()), intervals: [5_000] })
    .toBe('ready');
  const reportSec = (Date.parse(r.report!.generated_at!) - endedAt) / 1000;
  return { report: r, transcriptSec, reportSec };
}

const mmss = (s: number) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

/** Отчёт кандидата: шапка «משך», плеер, длительность файла записи, клик по последней реплике. */
export async function checkReportPage(business: Page, id: string, report: ReportJson) {
  const dur = report.attempt!.duration_seconds!;
  const segs = report.transcript?.segments || [];
  expect(segs.length, 'в транскрипте нет сегментов').toBeGreaterThan(0);
  expect(report.recording?.is_partial, 'recording.is_partial').toBe(false);

  await business.goto(`/candidates/${id}/report`);
  // Шапка: «השיחה הרשמית הסתיימה ב־… · משך MM:SS» (F-37); плеер «0:00 / MM:SS».
  await expect(business.getByText(new RegExp(`משך\\s*${mmss(dur)}`)).first()).toBeVisible({ timeout: 30_000 });
  const audio = business.locator('audio');
  await expect(audio).toHaveCount(1);
  await expect.poll(() => audio.evaluate((a: HTMLAudioElement) => a.currentSrc || a.src), { timeout: 30_000 }).not.toBe('');

  // Файл записи целиком: декодированная длительность ≈ длительности звонка (запись начинается после соединения, факт −3.5 с).
  const decoded = await audio.evaluate(async (a: HTMLAudioElement) => {
    const res = await fetch(a.currentSrc || a.src);
    const buf = await res.arrayBuffer();
    const ab = await new OfflineAudioContext(1, 1, 48000).decodeAudioData(buf);
    return { status: res.status, seconds: ab.duration };
  });
  expect(decoded.status).toBe(200);
  expect(Math.abs(decoded.seconds - dur), `файл ${decoded.seconds.toFixed(1)} с при звонке ${dur} с`).toBeLessThanOrEqual(10);

  // Последняя реплика: клик ставит плеер на её начало (F-37 AC8).
  const segBtns = business.getByRole('button').filter({ hasText: /(מועמד|לקוח)\s*\d{1,2}:\d{2}/ });
  await expect(segBtns).toHaveCount(segs.length);
  const last = segs[segs.length - 1];
  const lastBtn = segBtns.last();
  await expect(lastBtn).toContainText(mmss(last.start));
  await lastBtn.scrollIntoViewIfNeeded();
  await lastBtn.click();
  await expect.poll(() => audio.evaluate((a: HTMLAudioElement) => a.currentTime), { message: 'плеер не перешёл к последней реплике' }).toBeGreaterThanOrEqual(last.start - 1);
  const t = await audio.evaluate((a: HTMLAudioElement) => { a.pause(); return a.currentTime; });
  expect(t).toBeLessThanOrEqual(last.end + 2);
  // Текст плеера после паузы — время, где он остановился (начало реплики, ≤ 1–2 с проигрывания).
  await expect(business.getByText(new RegExp(`${mmss(t)}\\s*/\\s*${mmss(dur)}`)).first()).toBeVisible();
  return { decodedSec: decoded.seconds, segments: segs.length };
}

export async function openBusinessApi(business: Page): Promise<Api> {
  return openWithApi(business, '/candidates');
}
